from pathlib import Path
import json,time
base=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
expected_checkpoint="runs/A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2-3-a82c8f11"
result=base/"model_results"/(task+".json")
if result.is_file():
    raise SystemExit(10)
models=base/"models"
state=None
for name in ("CONTINUATION.json","STATE.json"):
    p=models/name
    if not p.is_file():
        continue
    try:
        o=json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        continue
    if isinstance(o,dict) and o.get("task_id")==task:
        state=o
        break
if not isinstance(state,dict):
    raise SystemExit(20)
if state.get("state")!="PAUSED_USAGE_LIMIT":
    raise SystemExit(21)
if state.get("next_action")!="resume_same_task":
    raise SystemExit(22)
if state.get("checkpoint")!=expected_checkpoint:
    raise SystemExit(24)
attempt=state.get("attempt")
if attempt not in (None,3):
    raise SystemExit(25)
retry_at=state.get("retry_at")
try:
    retry_at=float(retry_at or 0)
except Exception:
    raise SystemExit(23)
now=time.time()
if retry_at>now:
    delta=retry_at-now
    if delta<=300:
        time.sleep(delta+1)
    else:
        raise SystemExit(30)
raise SystemExit(0)
